import json, pathlib, xml.etree.ElementTree as ET
out=pathlib.Path(__file__).parent
src=pathlib.Path('daoanh/data/dila_import/biographies.2024-01/nexus_src/Mingsengzhuanchao.nexus.xml')
nodes=list(ET.parse(src).getroot().iter('nexus'))
rows=[]
def add(i,t,s,e,n=None):
 d=dict(index=i,id=nodes[i-1].get('id'),text_vi=t,summary_vi=s,event_type=e)
 if n:d['note']=n
 rows.append(d)
add(101,'[…] quán. Cảnh giới đạt được trở thành khuôn mẫu cho người học thiền. Sư tiết chế thân và lời nói, giữ đầy đủ giới luật thanh tịnh. Từng ở Giang Lăng dạy một tỳ-kheo tu thiền; vị ấy đạt được khá nhiều. Ấn nói với vị ấy: “Điều Thượng tọa đã học […]”.','Ấn hướng dẫn một tỳ-kheo tu thiền ở Giang Lăng.','teaching','Nguyên văn ghi 印 trong lời dẫn, khác tên 僧隱 ở truyện; giữ âm Ấn, chưa đồng nhất hai chữ.')
add(102,'[…] không bỏ phế. Sau trở về Đại tự ở Trường An, qua đời khi hơn sáu mươi tuổi.','Vị tăng trở về Đại tự ở Trường An rồi qua đời, hơn sáu mươi tuổi.','death')
add(103,'Huệ Lãm vốn họ Thành, người Tửu Tuyền. Đạo hạnh cao nghiêm, tiếng đức vang xa. Cùng với Huyền Cao […]','Huệ Lãm vốn họ Thành, quê Tửu Tuyền, nổi tiếng về đạo hạnh.','origin','Cụm 峻梁 có chữ 梁 khó xác định trong ngữ cảnh; bản dịch chỉ diễn đạt ý đạo hạnh cao nghiêm.')
add(104,'[…] bát của Phật. Học thiền với Đạt-ma-đạt ở Kế Tân. Năm Nguyên Gia thứ tư, ở trên cây, nhận được Bồ […]','Vị tăng học thiền với Đạt-ma-đạt ở Kế Tân.','study','Đoạn kết dừng ở chữ 菩, chưa đủ danh từ; không bổ sung phần còn thiếu.')
add(105,'[…] bát của Phật. Học thiền với Đạt-ma-đạt ở Kế Tân. Năm Nguyên Gia thứ tư, ở trên cây nhận được bản giới Bồ-tát. Khi vào định thấy Di-lặc nói: “Đây là ta trao cho ông. Những người tu đạo ở đất Hán phần nhiều phát đại […]”.','Vị tăng học thiền ở Kế Tân và được kể là thấy Di-lặc trao bản giới Bồ-tát.','miracle','Nguyên văn ghi 人定; dịch theo ngữ cảnh vào định, cần đối chiếu chữ 人 với 入.')
add(106,'[…] rồi trao lại cho Huệ Lãm, bảo Lãm: “Ông nên trở về nước phía đông, sẽ đem lại nhiều lợi ích”. Đến Vu Điền và Sa Châu, đại chúng đều tập hợp để thọ nhận từ thầy Lãm. Người cả nước chuyên tâm thiền định, nghĩ đến pháp mà quên ăn. Thục […]','Huệ Lãm truyền dạy cho đại chúng ở Vu Điền và Sa Châu.','teaching','于寘沙洲 được đọc là hai địa danh Vu Điền và Sa Châu; cần đối chiếu cách ngắt địa danh trong bản gốc.')
add(107,'[…] áo. Thân và đầu lở ngứa, ít tắm rửa. Trong niên hiệu Nghĩa Hy đời Tấn, thường ở Bạch Thổ [仁-二+彔] tại Quảng Lăng, cất tiếng hát để tự vui. Tiền công nhận được đều đem bố thí. Ban ngày đi lại, ban đêm ẩn mình, không ai biết chỗ nghỉ. Làm việc suốt ngày mà không đưa thức ăn vào miệng, chẳng ai biết dùng gì để nuôi thân. Các giọng khác nhau khắp tám phương đều làm được. Bấy giờ Cao Đàn Chi làm huyện lệnh Giang Đô, nghe chuyện lấy làm lạ […]','Vị tăng ở Quảng Lăng ca hát, làm việc và bố thí tiền công.','residence','Tên nơi chốn chứa gaiji [仁-二+彔] chưa xác định; 引葃 trong cụm ca hát cũng cần đối chiếu.')
add(108,'[…] ăn. Các giọng khác nhau khắp tám phương đều làm được. Bấy giờ Cao Đàn Chi làm huyện lệnh Giang Đô, nghe chuyện lấy làm lạ, sai viên lại đưa đến hỏi đáp. Lời đối đáp lanh lợi, khảo cứu việc xưa, hiểu biết rộng và giỏi biện luận về huyền học, Nho học. Làm một bài thơ: “Có dục cầu thì khổ vì không đủ; không dục cầu cũng không lo. Chưa bằng người thanh hư, thắt dây, khoác 玄喪. Rong chơi trong một đời, như thuyền không buộc trôi nổi”. Đàn tặng hai mươi tấm vải rồi cho về. Ra khỏi thành liền đem cho người qua đường; đi một quãng ngoài thành đã cho hết sạch. Không dùng họ tên […]','Cao Đàn Chi triệu vị tăng đến hỏi chuyện ở Giang Đô và tặng vải; vị tăng đem bố thí.','meeting','Các cụm 機[槤-車+康], 披玄喪, 汎苦 và 海行里外 có chữ khó đọc; giữ 玄喪, dịch các cụm còn lại theo nghĩa khả dĩ, cần đối chiếu.')
add(109,'[…] tranh nhau đến kính phụng. Phất áo đi về phương nam, nghỉ ở Đại tự núi Long Sơn, huyện Vĩnh Hưng. Thường ghé qua cá […]','Vị tăng đi về phương nam, nghỉ tại Đại tự núi Long Sơn ở huyện Vĩnh Hưng.','travel','Đoạn dừng ở 魚, chưa rõ danh từ tiếp theo; không bổ sung thành chợ cá hay người bán cá.')
add(110,'[…] tính tình sâu sắc, thường ôm lòng làm lợi ích. Giỏi bàn huyền học và Nho học, thấu hiểu thực tướng chân thật. Tạ Thiệu và Ngụy Mại Chi ở Cối Kê đều học rộng, luận bàn sâu, cùng theo thầy thọ học. Sau, các sa-môn ở cùng, ban đêm […]','Tạ Thiệu và Ngụy Mại Chi ở Cối Kê theo thầy học đạo.','study','Cụm 性用深點 có chữ 點 khó xác định; bản dịch diễn đạt ý khái quát, cần đối chiếu.')
add(111,'[…] đi. Đào Uyên Minh ở Tầm Dương ghi rằng ở Bạch Thổ [土*彔] gặp ba người khác thường, pháp sư là một trong số ấy (nói […]).','Đào Uyên Minh ghi pháp sư là một trong ba người khác thường gặp ở Bạch Thổ.','writing','Gaiji [土*彔] trong tên nơi chốn chưa xác định, giữ nguyên ký hiệu.')
add(112,'Huệ Thông không rõ từ đâu đến, thường thấy ở Tầm Dương. Hay tự xưng là Trịnh Tán kỵ. Giang Lăng […]','Huệ Thông thường xuất hiện ở Tầm Dương và tự xưng Trịnh Tán kỵ.','residence')
add(113,'Huệ Thông không rõ từ đâu đến, thường thấy ở Tầm Dương, hay tự xưng là Trịnh Tán kỵ. Biên Tăng Quy, người Giang Lăng, đi buôn đến Thọ Dương, sắp về Giang Lăng. Thông muốn gửi đồ theo ông, Tăng Quy không chịu nhận. Thông nài ép nên ông nhận, cũng không thấy nặng. Đi vài dặm rồi chia tay, Thông bảo: “Tôi có người vợ làm ni ở chùa Tam Tầng tại Kinh Châu, tên Huệ Tự. Ông đến đó hãy báo giúp rằng tôi sắp tới”. Nói xong bỗng biến mất. Tăng Quy […]','Huệ Thông nhờ Biên Tăng Quy báo tin cho ni Huệ Tự ở chùa Tam Tầng, Kinh Châu, rồi biến mất.','miracle')
add(114,'[…] “Ông đến đó hãy báo giúp rằng tôi sắp tới”. Nói xong bỗng biến mất. Tăng Quy đến Kinh Châu, kể đủ chuyện cho Huệ Tự. Vị ni ấy là người tu thiền, có đạo đức; vốn không có người anh này nên không hiểu vì sao. Sau đến Thọ Dương tìm, chẳng biết ở đâu. Thông về sau đến Kinh Châu, tới […]','Tăng Quy kể chuyện Huệ Thông cho ni Huệ Tự ở Kinh Châu; bà không nhận có người anh ấy.','meeting','Đoạn này ghi 兄 là anh, trong đoạn trước Huệ Thông gọi Huệ Tự là vợ; giữ bất nhất nguồn, không tự sửa. 結尼 cũng cần đối chiếu.')
add(115,'[…] châu. Đi cùng người khác, thấy mồ mả đều biết tên họ và dòng tộc. Ngày mồng tám tháng tư dự trai hội ở Đông tự, Thượng Minh, theo chúng tăng hành đạo. Giữa đám đông chỉ người mà nói: “Người này từng làm cướp”, chỉ như vậy vài người. Bọn cướp liền bỏ đi cùng lúc. Trên đường Giang Tân gặp một người, người ấy dùng roi ngựa […]','Vị tăng chỉ ra những người từng làm cướp tại trai hội ở Đông tự, Thượng Minh.','miracle')
add(116,'[…] như vậy vài người, bọn cướp liền cùng bỏ đi. Trên đường Giang Tân, có người dùng roi ngựa đánh Thông. Thông nói: “Ông nổi giận thì hãy về xem nhà mình thế nào”. Người ấy về đến nhà, lửa đã thiêu cháy nhà. Đầu niên hiệu Vĩnh Nguyên đời Tề, Thông đến xin rượu Nhậm Dạng, nói: “Tôi phải đi xa, mãi không còn gặp lại […]”.','Thông bị đánh trên đường Giang Tân rồi báo người đánh mình về xem căn nhà đang cháy.','miracle')
add(117,'[…] nhà rồi. Đầu niên hiệu Vĩnh Nguyên đời Tề, đến xin rượu Nhậm Dạng, nói: “Tôi phải đi xa, mãi không còn gặp lại. Xin gửi lời đến các thiện tri thức, đều nên tinh tấn, cẩn thận đừng thoái chuyển”. Uống rượu xong, đến nằm dưới đất bên tường phía đông chợ; xem thì đã chết. Vài chục ngày sau lại bỗng thấy ở chợ. Người trong chợ bèn nhìn theo, rất lâu sau mới mất hút (vân vân).','Vị tăng được thấy chết bên tường chợ rồi lại xuất hiện trong chợ vài chục ngày sau.','miracle','Cụm 慎幼退轉 được dịch theo ý khuyên không thoái chuyển; chữ 幼 cần đối chiếu.')
add(118,'Đạo Uông vốn họ Phan, người Trường Lạc. Gia quy và lời dạy trong nhà lấy thanh liêm, tiết kiệm làm nề nếp. Dáng […]','Đạo Uông vốn họ Phan, quê Trường Lạc, gia đình theo nếp thanh liêm và tiết kiệm.','origin','Đoạn kết 姿禪 không đủ nghĩa; chưa xác định chữ 禪 trong cụm này.')
add(119,'[…] cao đẹp, cao bảy thước bảy tấc. Thuở nhỏ đã có hiểu biết khác thường, người trong họ vốn lấy làm lạ. Sớm mồ côi, theo chú ở kinh sư. Mười ba tuổi đến nương Viễn công ở Lư Sơn xuất gia, nghiên cứu thiền và luật.','Vị tăng xuất gia với Viễn công ở Lư Sơn lúc mười ba tuổi, nghiên cứu thiền và luật.','ordination')
add(120,'[…] mồ côi, theo chú ở kinh sư. Mười ba tuổi đến nương Viễn công ở Lư Sơn xuất gia, nghiên cứu thiền và luật. Ở núi hơn mười năm; các kinh mới xuất hiện đều tinh thông. Kinh Đại Niết-bàn về sau truyền đến Giang […]','Vị tăng xuất gia và học thiền luật với Viễn công, ở Lư Sơn hơn mười năm.','study')
t='[…] luận, kiêm đọc cả sách ngoài Phật giáo; hiểu biết rộng, giỏi khai mở dẫn dắt, có tài biện luận. Các chùa Long Hoa, Kỳ Hoàn, Thiên Trúc, Vũ Đam, Tương Tư và Trường Thích tu sửa nền chùa, xây dựng tự viện, đều noi theo khuôn phép cao đẹp. Tu thiền, học tụng ngày đêm không ngừng. Phật pháp ở [崏-氏+民] Thục nhờ đó hưng thịnh. Đất Ích có người lưu ngụ […]'
for i in range(121,126):add(i,t,'Các chùa Long Hoa, Kỳ Hoàn và những chùa khác tu sửa, chuyên tu thiền tụng, khiến Phật pháp hưng thịnh.','teaching','Gaiji [崏-氏+民] chưa xác định; giữ nguyên. 無綴 có khả năng là chữ sai của ý không ngừng, cần đối chiếu.')
t='[…] trần. Những người tôn sùng đạo Phật, 殆將本半寧. Thường Nguyên Tổ ở Thục Quận từ nhỏ hiếu thảo với cha mẹ, tin sâu Đại pháp, mất năm Nguyên Gia thứ hai mươi tư. Báo mộng cho bạn rằng: “Tôi theo pháp sư Nhậm thọ giới Bồ-tát, nay được sinh lên trời Đâu-suất, làm thiên tử Thiện Lợi. Nhờ ông nói với các con đừng cúng tế nữa”. Thứ sử Lục Giản Tử, người Ngô Quận, đối đãi kính trọng […]'
for i in (126,127):add(i,t,'Thường Nguyên Tổ ở Thục Quận báo mộng đã sinh lên trời Đâu-suất sau khi thọ giới Bồ-tát.','miracle','Cụm 殆將本半寧 chưa rõ nghĩa, giữ Hán văn. Nguồn ghi 任法師 nên giữ pháp sư Nhậm, không đổi thành Đạo Uông; 門 và 天 cần đối chiếu.')
add(128,'[…] “Nhờ ông nói với các con đừng cúng tế nữa”. Thứ sử Lục Giản Tử, người Ngô Quận, đối đãi kính trọng […]','Thứ sử Lục Giản Tử, người Ngô Quận, được nhắc đến với việc đối đãi kính trọng.','other','Chữ 天 trong 天相禮遇 chưa rõ nghĩa; không thêm người được đối đãi vì đoạn thiếu.')
for i in (129,130):add(i,'Huệ Vĩnh là người Hà Nội, xuất gia làm đệ tử Trúc Đàm Hiện. Hiện chí hướng vững vàng, ngay thẳng. Thuở nhỏ […]','Huệ Vĩnh quê Hà Nội, xuất gia làm đệ tử Trúc Đàm Hiện.','ordination')
add(131,'[…] có tiết hạnh thanh cao, lớn lên chuộng ẩn cư, ở núi nuôi chí. Trong niên hiệu Thái Hòa đời Tấn, lập chùa dưới Bắc Lĩnh núi Lư Sơn ở Tầm Dương. Vĩnh thấy dưới Bắc Lĩnh còn ồn ào nên dời lên Nam Lĩnh, dựng phòng và điện đường giữa mây khói, đặt tên là tinh xá Lăng Vân. Từ đó dứt việc đời, ẩn cư nơi núi vắng, mặc áo cũ, ăn rau, chuyên thiền tụng. Người đến thường ngửi thấy hương thơm lan tỏa bên trong. Trong nhà Vĩnh thường có một con hổ; nếu khách sợ, sư đuổi lên núi, khách đi nó lại về, rất thuần phục. Vì vậy tăng tục đều kính ngưỡng. Vĩnh từng một mình xuống núi, trở về lúc chiều muộn; đến Ô Kiều, chủ doanh Ô Kiều […]','Huệ Vĩnh dời lên Nam Lĩnh ở Lư Sơn, dựng tinh xá Lăng Vân và chuyên tu thiền tụng.','residence','Các cụm 各內, 中堂 và 薄脫 có chữ khó xác định; cách dịch hương trong nhà, thường có hổ và chiều muộn cần đối chiếu.')
add(132,'[…] tăng tục kính ngưỡng. Vĩnh từng một mình xuống núi rồi trở về; đến Ô Kiều, chủ doanh Ô Kiều uống rượu say, cưỡi ngựa chắn đường, nhất quyết không cho qua. Trời gần tối, xin nhường cũng không chịu. Vĩnh rung tích trượng hướng về ngựa, ngựa giật mình hất ngược, chủ doanh ngã nhào xuống đất không dậy ngay được; ngựa tránh vào bụi cỏ. Sáng hôm sau chủ doanh vào núi sám hối, cho rằng Vĩnh dùng thần lực. Vĩnh nói: “Bần đạo biết ông uống rượu, vốn không trách. Chỉ gõ tích trượng như thường mà thành ra thế. Nếu quả thật có việc này thì hẳn thần hộ giới che chở thôi”. Vĩnh khiêm cung, chuyên cần khổ hạnh; dù bệnh vẫn thường […]','Huệ Vĩnh bị chủ doanh chặn ở Ô Kiều; sau sự cố ngã ngựa, người ấy đến xin lỗi.','meeting','Các cụm 薄脫 và 苦審有此改 có chữ khó xác định; chưa coi lời giải thích thần hộ giới là sự kiện được chứng minh.')
add(133,'[…] thì hẳn thần hộ giới che chở thôi. Vĩnh tính khiêm cung, chuyên cần khổ hạnh, dù mắc bệnh vẫn không bỏ việc trường trai. Thọ tám mươi ba tuổi, mất năm Thái Nguyên thứ năm đời Tấn (vân vân).','Huệ Vĩnh giữ trường trai ngay cả khi bệnh và qua đời ở tuổi tám mươi ba.','death')
add(134,'Huệ Tinh còn có tên Đàm Giới, vốn họ Trác, người Nam Dương. Ngoại binh lang đời Tấn, huyện lệnh [來*來] Dương tên Tiềm […]','Huệ Tinh còn tên Đàm Giới, họ Trác, quê Nam Dương.','origin','Gaiji [來*來] trong tên huyện chưa xác định, giữ nguyên ký hiệu.')
add(135,'Huệ Tinh còn có tên Đàm Giới, vốn họ Trác, người Nam Dương, là em của Tiềm, Ngoại binh lang đời Tấn kiêm huyện lệnh [來*來] Dương. Thuở nhỏ nhà nghèo, không có áo mặc nên không được theo thầy bạn. Vác củi, hơ lửa, mở […]','Huệ Tinh quê Nam Dương, thuở nhỏ nhà nghèo nên không được theo học thầy bạn.','origin','Gaiji [來*來] trong tên huyện chưa xác định, giữ nguyên ký hiệu.')
add(136,'[…] nghiền ngẫm sáu kinh. Sau nghe Vu Pháp Đạo giảng kinh Phóng Quang, mượn áo đến nghe, bảo anh rằng: “Nay mới hiểu Nho học nông gần, đạo giáo rộng thoáng. Em không thể tiếp tục chạy theo việc thế gian, chỉ muốn vượt ra ngoài đời”. Tiềm nói: “Quả thật mỗi người có chí riêng, sao có thể chỉ lo thực hiện chí mình?”. Năm mười chín tuổi […]','Vị tăng nghe Vu Pháp Đạo giảng kinh Phóng Quang rồi bày tỏ với anh ý muốn rời đời sống thế tục.','study','道教 trong lời nói được giữ là đạo giáo theo văn cảnh, chưa xác định là tên riêng Đạo giáo.')
add(137,'[…] năm mươi vạn lời, lấy lễ Phật làm việc chính. Bấy giờ pháp thiền chưa truyền đến, dựa kinh ngồi thiền một mình. Lâm Xuyên vương đời Tấn đối đãi kính trọng, cung cấp bốn món cần dùng. Sau cùng An ở chùa Thái Hậu tại Trường An. An […]','Vị tăng được Lâm Xuyên vương hỗ trợ, sau cùng An ở chùa Thái Hậu tại Trường An.','residence')
add(138,'[…] vương đối đãi kính trọng, cung cấp bốn món cần dùng. Sau cùng An ở chùa Thái Hậu tại Trường An. An […]','Vị tăng cùng An ở chùa Thái Hậu tại Trường An.','residence')
add(139,'[…] sau, trong niên hiệu Long An bị bệnh, miệng niệm Di-lặc không từng ngơi nghỉ. Đệ tử Trí Sinh chăm bệnh, hỏi: “Sao không nguyện sinh Tây phương mà chỉ xưng niệm Di-lặc?”. Đáp: “Chúng ta, Đạo An và tám người, trước đã phát nguyện sinh lên Đâu-suất, gặp mặt Di-lặc. Những người cùng nguyện đều đã được gặp trước, chỉ ta còn sống, nên muốn trọn bản nguyện”. Nói xong liền có ánh sáng chiếu thân, sắc mặt càng vui. Chốc lát qua đời, thọ bảy mươi tuổi, an táng bên phải mộ Đạo An (vân vân).','Vị tăng niệm Di-lặc lúc bệnh, qua đời ở tuổi bảy mươi và được an táng bên phải mộ Đạo An.','death','吾等道安八人 có thể hiểu nhóm tám người gồm Đạo An; cần đối chiếu cách ngắt, không cộng thêm thành chín người. 道願 cũng cần đối chiếu.')
add(140,'Trúc Pháp Thuần chưa rõ quê quán, ở chùa Hiển Nghĩa tại Sơn Âm, Cối Kê, tinh tấn […]','Trúc Pháp Thuần ở chùa Hiển Nghĩa, Sơn Âm, Cối Kê; chưa rõ quê quán.','residence')
add(141,'[…] khổ hạnh, tâm hướng đến vắng lặng. Đại chúng rất kính trọng, thỉnh làm tự chủ. Trong niên hiệu Nguyên Hưng đời Tấn, sửa tường chùa, đến Lan Thượng mua gỗ nhà cũ. Gần tối, cùng người chèo thuyền và bà chủ nhà đi vào hồ. Chốc lát gió nổi, mây phủ bốn bề, tự nghĩ chết cùng phụ nữ thật dễ chuốc nhục. Mưa tuyết dồn dập, sóng dữ cuồn cuộn, thuyền nhỏ bị nước tràn. Liền hướng về Quán Thế Âm cầu cứu và tụng kinh. Bỗng giữa hồ có thuyền trống lao ngang nhanh như bay, tới sát bên. Càng hết lòng tụng niệm. Chốc lát 至純; tìm hỏi riêng thì thuyền không có chủ. Sự cảm ứng như vậy (vân vân).','Vị tăng cầu Quán Thế Âm khi gặp bão trên hồ và được kể là gặp một thuyền trống cứu giúp.','miracle','有頃至純 và 船遂主無 có văn tự khó hiểu; giữ 至純, không tự bổ sung việc sang thuyền hay cập bờ.')
add(142,'Trúc Huệ Khánh là người Quảng Lăng, tâm thanh cao, suy nghĩ rộng thoáng, không trau chuốt lễ nghi thế tục, chuyên […]','Trúc Huệ Khánh quê Quảng Lăng, sống thanh cao và không chuộng lễ nghi thế tục.','origin')
add(143,'[…] được gọi là pháp sư, lòng hướng về đạo lý vượt ngoài điều giản lược. Trong niên hiệu Nghĩa Hy đời Tấn, du hành đến Trường An, tìm hiểu đạo học.','Vị pháp sư du hành đến Trường An trong niên hiệu Nghĩa Hy.','travel','理懷簡表 và 備浪道藝 có chữ khó xác định; cách dịch cần đối chiếu nguyên bản.')
add(144,'Vào thời Nguyên Hỷ đời Tống, lại vào Lư Sơn tìm các bậc đức hạnh hơn mình. Bấy giờ Kinh và Dương bị lũ lớn, nước dâng mênh mông. Khánh vừa đến Tiểu Lôi thì gió dữ nổi lên. Bạn đồng hành khỏe sức đều đã vào bến; thuyền Khánh chậm nặng, đến sau chưa kịp. Thần sóng Dương Hầu nổi giận, sóng vọt lên trời. Khánh không còn cách nào, chỉ trông mong nơi Phật, bèn chuyên tâm niệm Quán Thế Âm. Người trên bờ thấy thuyền đi ngược gió, rẽ sóng như có người kéo; trong chốc lát đến bờ an toàn. Từ đó gạt bỏ náo động, lắng tâm nơi thanh tịnh. Đến đâu cũng hoằng đạo; đệ tử thọ Tam quy, Ngũ giới thuộc mọi tầng lớp có hàng vạn người. Lời nói có sức cảm hóa như gió làm cỏ rạp xuống. Tạo chép nhiều kinh sách, thường tổ chức pháp hội. Thọ sáu mươi hai tuổi, mất năm Nguyên Hỷ thứ hai mươi chín (vân vân).','Huệ Khánh niệm Quán Thế Âm khi gặp sóng dữ trên đường đến Lư Sơn, rồi cập bờ an toàn.','miracle','Nguồn ghi 元喜 nên giữ Nguyên Hỷ, không tự sửa thành Nguyên Gia; 嚻磨 và 景風 có chữ cần đối chiếu.')
add(145,'[…] tổ chức pháp hội. Thọ sáu mươi hai tuổi, mất năm Nguyên Hỷ thứ hai mươi chín (vân vân).','Vị tăng qua đời ở tuổi sáu mươi hai sau thời gian tổ chức pháp hội.','death','Niên hiệu nguyên văn là 元喜, giữ Nguyên Hỷ, không tự sửa thành Nguyên Gia.')
add(146,'Đạo Hải là người Giang Lăng, nghiêm trì hạnh, chuyên cần tu tập, từ nhỏ đến lớn một lòng, an phận nghèo và giữ tiết kiệm, không đổi […]','Đạo Hải quê Giang Lăng, chuyên tu và sống thanh bần từ nhỏ đến lớn.','origin')
add(147,'[…] phẩm hạnh của mình. Từng ở chùa Trường Sa, khi trai kỳ mùa đông sắp hết, các tăng cùng tổ chức trai hội Vô Lượng Thọ.','Các tăng tổ chức trai hội Vô Lượng Thọ tại chùa Trường Sa khi trai kỳ mùa đông sắp hết.','other')
add(148,'Huệ Quả là người Dự Châu, giữ khuôn phép thanh tịnh và nếp sống giản dị từ thuở nhỏ, hiếu thảo phụng dưỡng cha mẹ, kính trọng thờ thầy.','Huệ Quả quê Dự Châu, từ nhỏ giữ nếp thanh tịnh, hiếu kính cha mẹ và thầy.','origin','Chữ trong 童[歹*專] chưa đọc được; giữ ký hiệu [歹*專] để đối chiếu, nghĩa tuổi nhỏ dựa vào chữ 童.')
rows[-1]['text_vi']=rows[-1]['text_vi'].replace('thuở nhỏ','thuở 童[歹*專]')
add(149,'Nhà nghèo, cơm áo không đủ. Năm Nguyên Hỷ thứ tư, mang sách đi về phương nam đến kinh sư, ở thiền phòng chùa Ngõa Quan. Bữa ăn thường thiếu nhưng không ăn cá thịt. Đốt hương, lễ sám, đặc biệt siêng tụng đọc; Thập Địa, Pháp Hoa, Tam thừa, Phương Đẳng đều thông hiểu. Tiếng thanh cao và danh tốt ngang với Tăng Cứ. Quả […]','Vị tăng đến kinh sư, ở thiền phòng chùa Ngõa Quan, giữ ăn chay và chuyên tụng đọc kinh.','residence','Nguyên văn ghi 元喜, giữ Nguyên Hỷ; 簟食 cần đối chiếu, dịch theo nghĩa bữa ăn thiếu thốn.')
add(150,'[…] khác biệt lớn là ở đây. Lòng nhân ái của Quả lan xa, làm cầu bến cho đời, đều như vậy. Thọ bảy mươi sáu tuổi, mất năm Thái Thủy thứ sáu (vân vân).','Quả được kính trọng vì lòng nhân ái và qua đời ở tuổi bảy mươi sáu.','death')
assert len(rows)==50
for d in rows:
 assert d['text_vi'].strip() and d['summary_vi'].strip()
 assert len(d['summary_vi'].split())<=30,(d['index'],len(d['summary_vi'].split()))
 assert not any('/' in str(d.get(k,'')) for k in ('text_vi','summary_vi','event_type','note')),d['index']
 assert d['id']==nodes[d['index']-1].get('id')
(out/'batch03.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
print('batch03 PASS: 50 records, indices101-150, ids, nonempty, summary<=30, slash=0')
